#include <iostream>
#include <utility>
#include <vector>

std::pair<int, int> MinMax(const std::vector<int>& values);

int main()
{
    int n;
    while (std::cin >> n)
    {
        std::vector<int> values(n);
        for (int i = 0; i < n; i++)
        {
            std::cin >> values[i];
        }
        std::pair<int, int> r = MinMax(values);
        std::cout << r.first << " " << r.second << "\n";
    }
    return 0;
}

