"""Random non-empty arrays, biased all-positive or all-negative half the time
so a zero-seeded minimum or maximum is caught."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    n = rng.randint(1, 12)
    kind = rng.choice(["mixed", "positive", "negative"])
    if kind == "positive":
        values = [rng.randint(1, 100) for _ in range(n)]
    elif kind == "negative":
        values = [rng.randint(-100, -1) for _ in range(n)]
    else:
        values = [rng.randint(-100, 100) for _ in range(n)]
    return {"name": "%d %s values #%d" % (n, kind, index),
            "stdin": "%d\n%s\n" % (n, " ".join(map(str, values)))}
